package com.ankit.joblens.profile;
import java.io.InputStream; import java.util.*; import org.apache.tika.Tika; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class ResumeProfileService { private final ResumeProfileRepository repo; private final Tika tika=new Tika(); public ResumeProfileService(ResumeProfileRepository repo){this.repo=repo;} public Map<String,Object> readAndApply(MultipartFile file)throws Exception{if(file.isEmpty())throw new IllegalArgumentException("Resume file is empty");String text;try(InputStream in=file.getInputStream()){text=tika.parseToString(in);}if(text.isBlank())throw new IllegalArgumentException("Resume text could not be extracted");long id=repo.id();List<String> skills=repo.catalog().stream().filter(s->text.toLowerCase(Locale.ROOT).contains(s.toLowerCase(Locale.ROOT))).toList();repo.save(id,text.lines().filter(l->!l.isBlank()).findFirst().orElse("Resume profile"),skills);return Map.of("profileId",id,"fileName",file.getOriginalFilename(),"detectedSkills",skills,"reviewRequired",true);} public Map<String,Object> profile(){long id=repo.id();return Map.of("id",id,"skills",repo.skills(id));} public Map<String,Object> updateSkills(List<String> skills){long id=repo.id();repo.save(id,"Resume profile",skills);return profile();}}
